static void aw_Infinity_process_fast(void *aw_state, int16_t *aw_out,
    const int16_t *aw_in, int32_t sampleFrames, uint32_t aw_channels) {
    aw_Infinity_fast_t *aw_s = (aw_Infinity_fast_t *)aw_state;
    const double aw_sample_rate = aw_s->aw_sample_rate;
    (void)aw_sample_rate;
    float *biquadA = aw_s->biquadA;
    float *biquadB = aw_s->biquadB;
    float *biquadC = aw_s->biquadC;
    float *aAL = aw_s->aAL;
    float *aBL = aw_s->aBL;
    float *aCL = aw_s->aCL;
    float *aDL = aw_s->aDL;
    float *aEL = aw_s->aEL;
    float *aFL = aw_s->aFL;
    float *aGL = aw_s->aGL;
    float *aHL = aw_s->aHL;
    float *aIL = aw_s->aIL;
    float *aJL = aw_s->aJL;
    float *aKL = aw_s->aKL;
    float *aLL = aw_s->aLL;
    float *aAR = aw_s->aAR;
    float *aBR = aw_s->aBR;
    float *aCR = aw_s->aCR;
    float *aDR = aw_s->aDR;
    float *aER = aw_s->aER;
    float *aFR = aw_s->aFR;
    float *aGR = aw_s->aGR;
    float *aHR = aw_s->aHR;
    float *aIR = aw_s->aIR;
    float *aJR = aw_s->aJR;
    float *aKR = aw_s->aKR;
    float *aLR = aw_s->aLR;
    int countA = aw_s->countA;
    int delayA = aw_s->delayA;
    int countB = aw_s->countB;
    int delayB = aw_s->delayB;
    int countC = aw_s->countC;
    int delayC = aw_s->delayC;
    int countD = aw_s->countD;
    int delayD = aw_s->delayD;
    int countE = aw_s->countE;
    int delayE = aw_s->delayE;
    int countF = aw_s->countF;
    int delayF = aw_s->delayF;
    int countG = aw_s->countG;
    int delayG = aw_s->delayG;
    int countH = aw_s->countH;
    int delayH = aw_s->delayH;
    int countI = aw_s->countI;
    int delayI = aw_s->delayI;
    int countJ = aw_s->countJ;
    int delayJ = aw_s->delayJ;
    int countK = aw_s->countK;
    int delayK = aw_s->delayK;
    int countL = aw_s->countL;
    int delayL = aw_s->delayL;
    float feedbackAL = aw_s->feedbackAL;
    float feedbackBL = aw_s->feedbackBL;
    float feedbackCL = aw_s->feedbackCL;
    float feedbackDL = aw_s->feedbackDL;
    float feedbackEL = aw_s->feedbackEL;
    float feedbackFL = aw_s->feedbackFL;
    float feedbackGL = aw_s->feedbackGL;
    float feedbackHL = aw_s->feedbackHL;
    float feedbackAR = aw_s->feedbackAR;
    float feedbackBR = aw_s->feedbackBR;
    float feedbackCR = aw_s->feedbackCR;
    float feedbackDR = aw_s->feedbackDR;
    float feedbackER = aw_s->feedbackER;
    float feedbackFR = aw_s->feedbackFR;
    float feedbackGR = aw_s->feedbackGR;
    float feedbackHR = aw_s->feedbackHR;
    uint32_t fpdL = aw_s->fpdL;
    uint32_t fpdR = aw_s->fpdR;
    float A = aw_s->A;
    float B = aw_s->B;
    float C = aw_s->C;
    float D = aw_s->D;
    {
	
	biquadC[0] = biquadB[0] = biquadA[0] = ((pow(A,2)*9900.0)+100.0) / aw_sample_rate;
	biquadA[1] = 0.618033988749894848204586;
	biquadB[1] = (A*0.5)+0.118033988749894848204586;
    biquadC[1] = 0.5;
	
	double K = tan(M_PI * biquadA[0]); //lowpass
	double norm = 1.0 / (1.0 + K / biquadA[1] + K * K);
	biquadA[2] = K * K * norm;
	biquadA[3] = 2.0 * biquadA[2];
	biquadA[4] = biquadA[2];
	biquadA[5] = 2.0 * (K * K - 1.0) * norm;
	biquadA[6] = (1.0 - K / biquadA[1] + K * K) * norm;
	
	K = tan(M_PI * biquadA[0]);
	norm = 1.0 / (1.0 + K / biquadB[1] + K * K);
	biquadB[2] = K * K * norm;
	biquadB[3] = 2.0 * biquadB[2];
	biquadB[4] = biquadB[2];
	biquadB[5] = 2.0 * (K * K - 1.0) * norm;
	biquadB[6] = (1.0 - K / biquadB[1] + K * K) * norm;
	
	K = tan(M_PI * biquadC[0]);
	norm = 1.0 / (1.0 + K / biquadC[1] + K * K);
	biquadC[2] = K * K * norm;
	biquadC[3] = 2.0 * biquadC[2];
	biquadC[4] = biquadC[2];
	biquadC[5] = 2.0 * (K * K - 1.0) * norm;
	biquadC[6] = (1.0 - K / biquadC[1] + K * K) * norm;
	
	double damping = pow(B,2)*0.5;
	
	double size = (pow(C,2)*90.0)+10.0;
	
	double wet = D;
	
	delayA = 79*size;
	delayB = 73*size;
	delayC = 71*size;
	delayD = 67*size;
	delayE = 61*size;
	delayF = 59*size;
	delayG = 53*size;
	delayH = 47*size;
	
	delayI = 43*size;
	delayJ = 41*size;
	delayK = 37*size;
	delayL = 31*size;
	
    const float aw_f_damping = (float)damping;
	const float aw_f_wet = (float)wet;
	const float aw_inv0 = 1.0f / (8.0f);
	while (--sampleFrames >= 0)
    {
		const float aw_inL = AW_IN_L(aw_in);
		const float aw_inR = AW_IN_R(aw_in, aw_channels);
		float aw_outL = 0.0f, aw_outR = 0.0f;/* aw:loop */
		float inputSampleL = aw_inL;
		float inputSampleR = aw_inR;
		if (fabsf(inputSampleL)<1.18e-23f) inputSampleL = fpdL * 1.18e-17f;
		if (fabsf(inputSampleR)<1.18e-23f) inputSampleR = fpdR * 1.18e-17f;
		float drySampleL = inputSampleL;
		float drySampleR = inputSampleR;
		
		float tempSampleL = (inputSampleL * biquadA[2]) + biquadA[7];
		biquadA[7] = (inputSampleL * biquadA[3]) - (tempSampleL * biquadA[5]) + biquadA[8];
		biquadA[8] = (inputSampleL * biquadA[4]) - (tempSampleL * biquadA[6]);
		inputSampleL = tempSampleL; //like mono AU, 7 and 8 store L channel
		
		float tempSampleR = (inputSampleR * biquadA[2]) + biquadA[9];
		biquadA[9] = (inputSampleR * biquadA[3]) - (tempSampleR * biquadA[5]) + biquadA[10];
		biquadA[10] = (inputSampleR * biquadA[4]) - (tempSampleR * biquadA[6]);
		inputSampleR = tempSampleR; //note: 9 and 10 store the R channel
		
		inputSampleL *= aw_f_wet;
		inputSampleR *= aw_f_wet;
		//we're going to use this as a kind of balance since the reverb buildup can be so large
		inputSampleL *= 0.5f;
		inputSampleR *= 0.5f;
				
		float allpassIL = inputSampleL;
		float allpassJL = inputSampleL;
		float allpassKL = inputSampleL;
		float allpassLL = inputSampleL;
		
		float allpassIR = inputSampleR;
		float allpassJR = inputSampleR;
		float allpassKR = inputSampleR;
		float allpassLR = inputSampleR;
		
		int allpasstemp = countI + 1;
		if (allpasstemp < 0 || allpasstemp > delayI) {allpasstemp = 0;}
		allpassIL -= aIL[allpasstemp]*0.5f;
		aIL[countI] = allpassIL;
		allpassIL *= 0.5f;
		allpassIR -= aIR[allpasstemp]*0.5f;
		aIR[countI] = allpassIR;
		allpassIR *= 0.5f;
		countI++; if (countI < 0 || countI > delayI) {countI = 0;}		
		allpassIL += (aIL[countI]);
		allpassIR += (aIR[countI]);
		
		allpasstemp = countJ + 1;
		if (allpasstemp < 0 || allpasstemp > delayJ) {allpasstemp = 0;}
		allpassJL -= aJL[allpasstemp]*0.5f;
		aJL[countJ] = allpassJL;
		allpassJL *= 0.5f;
		allpassJR -= aJR[allpasstemp]*0.5f;
		aJR[countJ] = allpassJR;
		allpassJR *= 0.5f;
		countJ++; if (countJ < 0 || countJ > delayJ) {countJ = 0;}		
		allpassJL += (aJL[countJ]);
		allpassJR += (aJR[countJ]);
		
		allpasstemp = countK + 1;
		if (allpasstemp < 0 || allpasstemp > delayK) {allpasstemp = 0;}
		allpassKL -= aKL[allpasstemp]*0.5f;
		aKL[countK] = allpassKL;
		allpassKL *= 0.5f;
		allpassKR -= aKR[allpasstemp]*0.5f;
		aKR[countK] = allpassKR;
		allpassKR *= 0.5f;
		countK++; if (countK < 0 || countK > delayK) {countK = 0;}		
		allpassKL += (aKL[countK]);
		allpassKR += (aKR[countK]);
		
		allpasstemp = countL + 1;
		if (allpasstemp < 0 || allpasstemp > delayL) {allpasstemp = 0;}
		allpassLL -= aLL[allpasstemp]*0.5f;
		aLL[countL] = allpassLL;
		allpassLL *= 0.5f;
		allpassLR -= aLR[allpasstemp]*0.5f;
		aLR[countL] = allpassLR;
		allpassLR *= 0.5f;
		countL++; if (countL < 0 || countL > delayL) {countL = 0;}		
		allpassLL += (aLL[countL]);		
		allpassLR += (aLR[countL]);		
		//the big allpass in front of everything
		
		aAL[countA] = allpassLL + feedbackAL;
		aBL[countB] = allpassKL + feedbackBL;
		aCL[countC] = allpassJL + feedbackCL;
		aDL[countD] = allpassIL + feedbackDL;
		aEL[countE] = allpassIL + feedbackEL;
		aFL[countF] = allpassJL + feedbackFL;
		aGL[countG] = allpassKL + feedbackGL;
		aHL[countH] = allpassLL + feedbackHL; //L
		
		aAR[countA] = allpassLR + feedbackAR;
		aBR[countB] = allpassKR + feedbackBR;
		aCR[countC] = allpassJR + feedbackCR;
		aDR[countD] = allpassIR + feedbackDR;
		aER[countE] = allpassIR + feedbackER;
		aFR[countF] = allpassJR + feedbackFR;
		aGR[countG] = allpassKR + feedbackGR;
		aHR[countH] = allpassLR + feedbackHR; //R
		
		countA++; if (countA < 0 || countA > delayA) {countA = 0;}
		countB++; if (countB < 0 || countB > delayB) {countB = 0;}
		countC++; if (countC < 0 || countC > delayC) {countC = 0;}
		countD++; if (countD < 0 || countD > delayD) {countD = 0;}
		countE++; if (countE < 0 || countE > delayE) {countE = 0;}
		countF++; if (countF < 0 || countF > delayF) {countF = 0;}
		countG++; if (countG < 0 || countG > delayG) {countG = 0;}
		countH++; if (countH < 0 || countH > delayH) {countH = 0;}
		//the Householder matrices (shared between channels, offset is stereo)

		
		float infiniteAL = (aAL[countA-((countA > delayA)?delayA+1:0)] * (1-(aw_f_damping-aw_floorf(aw_f_damping))) );
		infiniteAL += (aAL[countA+1-((countA+1 > delayA)?delayA+1:0)] * ((aw_f_damping-aw_floorf(aw_f_damping))) );
		float infiniteBL = aBL[countB-((countB > delayB)?delayB+1:0)];
		float infiniteCL = aCL[countC-((countC > delayC)?delayC+1:0)];
		float infiniteDL = aDL[countD-((countD > delayD)?delayD+1:0)];
		
		float infiniteAR = (aAR[countA-((countA > delayA)?delayA+1:0)] * (1-(aw_f_damping-aw_floorf(aw_f_damping))) );
		infiniteAR += (aAR[countA+1-((countA+1 > delayA)?delayA+1:0)] * ((aw_f_damping-aw_floorf(aw_f_damping))) );
		float infiniteBR = aBR[countB-((countB > delayB)?delayB+1:0)];
		float infiniteCR = aCR[countC-((countC > delayC)?delayC+1:0)];
		float infiniteDR = aDR[countD-((countD > delayD)?delayD+1:0)];
		
		float infiniteEL = (aEL[countE-((countE > delayE)?delayE+1:0)] * (1-(aw_f_damping-aw_floorf(aw_f_damping))) );
		infiniteEL += (aEL[countE+1-((countE+1 > delayE)?delayE+1:0)] * ((aw_f_damping-aw_floorf(aw_f_damping))) );
		float infiniteFL = aFL[countF-((countF > delayF)?delayF+1:0)];
		float infiniteGL = aGL[countG-((countG > delayG)?delayG+1:0)];
		float infiniteHL = aHL[countH-((countH > delayH)?delayH+1:0)];
		
		float infiniteER = (aER[countE-((countE > delayE)?delayE+1:0)] * (1-(aw_f_damping-aw_floorf(aw_f_damping))) );
		infiniteER += (aER[countE+1-((countE+1 > delayE)?delayE+1:0)] * ((aw_f_damping-aw_floorf(aw_f_damping))) );
		float infiniteFR = aFR[countF-((countF > delayF)?delayF+1:0)];
		float infiniteGR = aGR[countG-((countG > delayG)?delayG+1:0)];
		float infiniteHR = aHR[countH-((countH > delayH)?delayH+1:0)];
		
		float dialBackAL = 0.5f;
		float dialBackEL = 0.5f;
		float dialBackDryL = 0.5f;
		if (fabsf(infiniteAL)>0.4f) dialBackAL -= ((fabsf(infiniteAL)-0.4f)*0.2f);
		if (fabsf(infiniteEL)>0.4f) dialBackEL -= ((fabsf(infiniteEL)-0.4f)*0.2f);
		if (fabsf(drySampleL)>0.4f) dialBackDryL -= ((fabsf(drySampleL)-0.4f)*0.2f);
		//we're compressing things subtly so we can feed energy in and not overload
		
		float dialBackAR = 0.5f;
		float dialBackER = 0.5f;
		float dialBackDryR = 0.5f;
		if (fabsf(infiniteAR)>0.4f) dialBackAR -= ((fabsf(infiniteAR)-0.4f)*0.2f);
		if (fabsf(infiniteER)>0.4f) dialBackER -= ((fabsf(infiniteER)-0.4f)*0.2f);
		if (fabsf(drySampleR)>0.4f) dialBackDryR -= ((fabsf(drySampleR)-0.4f)*0.2f);
		//we're compressing things subtly so we can feed energy in and not overload
		
		feedbackAL = (infiniteAL - (infiniteBL + infiniteCL + infiniteDL)) * dialBackAL;
		feedbackBL = (infiniteBL - (infiniteAL + infiniteCL + infiniteDL)) * dialBackDryL;
		feedbackCL = (infiniteCL - (infiniteAL + infiniteBL + infiniteDL)) * dialBackDryL;
		feedbackDL = (infiniteDL - (infiniteAL + infiniteBL + infiniteCL)) * dialBackDryL; //Householder feedback matrix, L
		
		feedbackEL = (infiniteEL - (infiniteFL + infiniteGL + infiniteHL)) * dialBackEL;
		feedbackFL = (infiniteFL - (infiniteEL + infiniteGL + infiniteHL)) * dialBackDryL;
		feedbackGL = (infiniteGL - (infiniteEL + infiniteFL + infiniteHL)) * dialBackDryL;
		feedbackHL = (infiniteHL - (infiniteEL + infiniteFL + infiniteGL)) * dialBackDryL; //Householder feedback matrix, L
		
		feedbackAR = (infiniteAR - (infiniteBR + infiniteCR + infiniteDR)) * dialBackAR;
		feedbackBR = (infiniteBR - (infiniteAR + infiniteCR + infiniteDR)) * dialBackDryR;
		feedbackCR = (infiniteCR - (infiniteAR + infiniteBR + infiniteDR)) * dialBackDryR;
		feedbackDR = (infiniteDR - (infiniteAR + infiniteBR + infiniteCR)) * dialBackDryR; //Householder feedback matrix, R
		
		feedbackER = (infiniteER - (infiniteFR + infiniteGR + infiniteHR)) * dialBackER;
		feedbackFR = (infiniteFR - (infiniteER + infiniteGR + infiniteHR)) * dialBackDryR;
		feedbackGR = (infiniteGR - (infiniteER + infiniteFR + infiniteHR)) * dialBackDryR;
		feedbackHR = (infiniteHR - (infiniteER + infiniteFR + infiniteGR)) * dialBackDryR; //Householder feedback matrix, R
		
		inputSampleL = (infiniteAL + infiniteBL + infiniteCL + infiniteDL + infiniteEL + infiniteFL + infiniteGL + infiniteHL)* aw_inv0;
		inputSampleR = (infiniteAR + infiniteBR + infiniteCR + infiniteDR + infiniteER + infiniteFR + infiniteGR + infiniteHR)* aw_inv0;
		
		tempSampleL = (inputSampleL * biquadB[2]) + biquadB[7];
		biquadB[7] = (inputSampleL * biquadB[3]) - (tempSampleL * biquadB[5]) + biquadB[8];
		biquadB[8] = (inputSampleL * biquadB[4]) - (tempSampleL * biquadB[6]);
		inputSampleL = tempSampleL; //like mono AU, 7 and 8 store L channel
		
		tempSampleR = (inputSampleR * biquadB[2]) + biquadB[9];
		biquadB[9] = (inputSampleR * biquadB[3]) - (tempSampleR * biquadB[5]) + biquadB[10];
		biquadB[10] = (inputSampleR * biquadB[4]) - (tempSampleR * biquadB[6]);
		inputSampleR = tempSampleR; //note: 9 and 10 store the R channel
		
		if (inputSampleL > 1.0f) inputSampleL = 1.0f;
		if (inputSampleL < -1.0f) inputSampleL = -1.0f;
		if (inputSampleR > 1.0f) inputSampleR = 1.0f;
		if (inputSampleR < -1.0f) inputSampleR = -1.0f;
		//without this, you can get a NaN condition where it spits out DC offset at full blast!
		
		inputSampleL = asinf(inputSampleL);
		inputSampleR = asinf(inputSampleR);
		
		tempSampleL = (inputSampleL * biquadC[2]) + biquadC[7];
		biquadC[7] = (inputSampleL * biquadC[3]) - (tempSampleL * biquadC[5]) + biquadC[8];
		biquadC[8] = (inputSampleL * biquadC[4]) - (tempSampleL * biquadC[6]);
		inputSampleL = tempSampleL; //like mono AU, 7 and 8 store L channel
		
		tempSampleR = (inputSampleR * biquadC[2]) + biquadC[9];
		biquadC[9] = (inputSampleR * biquadC[3]) - (tempSampleR * biquadC[5]) + biquadC[10];
		biquadC[10] = (inputSampleR * biquadC[4]) - (tempSampleR * biquadC[6]);
		inputSampleR = tempSampleR; //note: 9 and 10 store the R channel
		
		if (aw_f_wet !=1.0f) {
			inputSampleL = (inputSampleL * aw_f_wet) + (drySampleL * (1.0f-aw_f_wet));
			inputSampleR = (inputSampleR * aw_f_wet) + (drySampleR * (1.0f-aw_f_wet));
		}
		fpdL ^= fpdL << 13; fpdL ^= fpdL >> 17; fpdL ^= fpdL << 5;
		fpdR ^= fpdR << 13; fpdR ^= fpdR >> 17; fpdR ^= fpdR << 5;
		//end 32 bit stereo floating point dither
		
		aw_outL = inputSampleL;
		aw_outR = inputSampleR;
    /* aw:end */		AW_OUT_FAST(aw_out, aw_channels, aw_outL, aw_outR);
		aw_in += aw_channels;
		aw_out += aw_channels;
	}
}
    aw_s->countA = countA;
    aw_s->delayA = delayA;
    aw_s->countB = countB;
    aw_s->delayB = delayB;
    aw_s->countC = countC;
    aw_s->delayC = delayC;
    aw_s->countD = countD;
    aw_s->delayD = delayD;
    aw_s->countE = countE;
    aw_s->delayE = delayE;
    aw_s->countF = countF;
    aw_s->delayF = delayF;
    aw_s->countG = countG;
    aw_s->delayG = delayG;
    aw_s->countH = countH;
    aw_s->delayH = delayH;
    aw_s->countI = countI;
    aw_s->delayI = delayI;
    aw_s->countJ = countJ;
    aw_s->delayJ = delayJ;
    aw_s->countK = countK;
    aw_s->delayK = delayK;
    aw_s->countL = countL;
    aw_s->delayL = delayL;
    aw_s->feedbackAL = feedbackAL;
    aw_s->feedbackBL = feedbackBL;
    aw_s->feedbackCL = feedbackCL;
    aw_s->feedbackDL = feedbackDL;
    aw_s->feedbackEL = feedbackEL;
    aw_s->feedbackFL = feedbackFL;
    aw_s->feedbackGL = feedbackGL;
    aw_s->feedbackHL = feedbackHL;
    aw_s->feedbackAR = feedbackAR;
    aw_s->feedbackBR = feedbackBR;
    aw_s->feedbackCR = feedbackCR;
    aw_s->feedbackDR = feedbackDR;
    aw_s->feedbackER = feedbackER;
    aw_s->feedbackFR = feedbackFR;
    aw_s->feedbackGR = feedbackGR;
    aw_s->feedbackHR = feedbackHR;
    aw_s->fpdL = fpdL;
    aw_s->fpdR = fpdR;
}

static const uint32_t aw_Infinity_offsets_fast[] = {offsetof(aw_Infinity_fast_t, A), offsetof(aw_Infinity_fast_t, B), offsetof(aw_Infinity_fast_t, C), offsetof(aw_Infinity_fast_t, D)};
#endif

